/**
 * Configuration Manager
 * Handles global settings and credentials
 */

const fs = require('fs');
const path = require('path');

class ConfigManager {
  constructor(configPath = './kumva-config.json') {
    this.configPath = configPath;
    this.config = this.loadConfig();
  }

  /**
   * Load configuration from file
   */
  loadConfig() {
    try {
      if (fs.existsSync(this.configPath)) {
        const data = fs.readFileSync(this.configPath, 'utf8');
        return JSON.parse(data);
      }
    } catch (error) {
      console.error('Error loading config:', error.message);
    }

    // Return default config
    return {
      africasTalking: {
        apiKey: '',
        username: ''
      },
      redis: {
        host: 'localhost',
        port: 6379,
        db: 0
      },
      storage: {
        path: './kumva-data'
      },
      webhook: {
        port: 3000,
        basePath: '/kumva'
      },
      defaults: {
        timeout: '30s',
        messageType: 'sms'
      }
    };
  }

  /**
   * Save configuration to file
   */
  saveConfig() {
    try {
      const dir = path.dirname(this.configPath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }

      fs.writeFileSync(this.configPath, JSON.stringify(this.config, null, 2));
      return { success: true };
    } catch (error) {
      console.error('Error saving config:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Get Africa's Talking credentials
   */
  getAfricasTalkingConfig() {
    return this.config.africasTalking || {};
  }

  /**
   * Set Africa's Talking credentials
   */
  setAfricasTalkingConfig(credentials) {
    this.config.africasTalking = {
      ...this.config.africasTalking,
      ...credentials
    };
    return this.saveConfig();
  }

  /**
   * Get Redis configuration
   */
  getRedisConfig() {
    return this.config.redis || {};
  }

  /**
   * Set Redis configuration
   */
  setRedisConfig(redisConfig) {
    this.config.redis = {
      ...this.config.redis,
      ...redisConfig
    };
    return this.saveConfig();
  }

  /**
   * Get storage path
   */
  getStoragePath() {
    return this.config.storage?.path || './kumva-data';
  }

  /**
   * Set storage path
   */
  setStoragePath(path) {
    if (!this.config.storage) {
      this.config.storage = {};
    }
    this.config.storage.path = path;
    return this.saveConfig();
  }

  /**
   * Get webhook configuration
   */
  getWebhookConfig() {
    return this.config.webhook || {};
  }

  /**
   * Set webhook configuration
   */
  setWebhookConfig(webhookConfig) {
    this.config.webhook = {
      ...this.config.webhook,
      ...webhookConfig
    };
    return this.saveConfig();
  }

  /**
   * Get default configuration
   */
  getDefaults() {
    return this.config.defaults || {};
  }

  /**
   * Set default configuration
   */
  setDefaults(defaults) {
    this.config.defaults = {
      ...this.config.defaults,
      ...defaults
    };
    return this.saveConfig();
  }

  /**
   * Get specific configuration value
   */
  get(key, defaultValue = null) {
    const keys = key.split('.');
    let value = this.config;

    for (const k of keys) {
      if (value && typeof value === 'object') {
        value = value[k];
      } else {
        return defaultValue;
      }
    }

    return value !== undefined ? value : defaultValue;
  }

  /**
   * Set specific configuration value
   */
  set(key, value) {
    const keys = key.split('.');
    let obj = this.config;

    for (let i = 0; i < keys.length - 1; i++) {
      const k = keys[i];
      if (!obj[k] || typeof obj[k] !== 'object') {
        obj[k] = {};
      }
      obj = obj[k];
    }

    obj[keys[keys.length - 1]] = value;
    return this.saveConfig();
  }

  /**
   * Validate if Africa's Talking is configured
   */
  isAfricasTalkingConfigured() {
    const config = this.getAfricasTalkingConfig();
    return !!(config.apiKey && config.username);
  }

  /**
   * Validate configuration
   */
  validate() {
    const errors = [];

    if (!this.isAfricasTalkingConfigured()) {
      errors.push('Africa\'s Talking credentials are not configured');
    }

    const redisConfig = this.getRedisConfig();
    if (!redisConfig.host || !redisConfig.port) {
      errors.push('Redis configuration is incomplete');
    }

    return {
      valid: errors.length === 0,
      errors
    };
  }
}

module.exports = ConfigManager;